def blocks(js):
    parts = re.split(r'(?m)^(?=  S\.push\(\{name: )', js)
    return parts[0], parts[1:]

for slug, adds in ADD.items():
    jsp, jp = T / f'{slug}.js', T / f'{slug}.json'
    js = jsp.read_text(encoding='utf8'); cfg = json.loads(jp.read_text(encoding='utf8'))
    pre, bl = blocks(js)
    names = [re.match(r"  S\.push\(\{name: '([^']+)'", b).group(1) for b in bl]
    caps = cfg['cap']
    assert names == [c[0] for c in caps], (slug, names)
    for after, js_new, cname, ctext in adds:
        i = [re.match(r"  S\.push\(\{name: '([^']+)'", b) or re.match(r'  S\.push\(\{name: "([^"]+)"', b) for b in bl]
        nm = [m.group(1) for m in i]
        k = nm.index(after)
        bl.insert(k + 1, js_new); caps.insert(k + 1, [cname, ctext])
    jsp.write_text(pre + ''.join(bl), encoding='utf8'); jp.write_text(json.dumps(cfg, ensure_ascii=False, indent=1), encoding='utf8')
    print(slug, len(bl), 'scenes')
